-- ----------------------------
-- Table structure for `candidates`
-- ----------------------------
DROP TABLE IF EXISTS `candidates`;
CREATE TABLE `candidates` (
  `id` varchar(50) NOT NULL,
  `job_id` int(11) DEFAULT NULL,
  `name` varchar(255) DEFAULT 'Unknown',
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `filename` varchar(255) DEFAULT NULL,
  `full_text` longtext DEFAULT NULL,
  `stripped_text` longtext DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Review',
  `recommendation` varchar(50) DEFAULT 'Pending',
  `overall_score` int(11) DEFAULT 0,
  `skills_match` int(11) DEFAULT 0,
  `exp_match` int(11) DEFAULT 0,
  `edu_match` int(11) DEFAULT 0,
  `summary` text DEFAULT NULL,
  `education` text DEFAULT NULL,
  `experience` text DEFAULT NULL,
  `skills` text DEFAULT NULL,
  `strengths` text DEFAULT NULL,
  `gaps` text DEFAULT NULL,
  `relevance_label` varchar(100) DEFAULT NULL,
  `note` text DEFAULT NULL,
  `suggested_question` text DEFAULT NULL,
  `screened` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `user_id` int(11) DEFAULT NULL,
  `resume_path` varchar(255) DEFAULT NULL,
  `youtube_url` varchar(255) DEFAULT NULL,
  `hiring_verdict` varchar(100) DEFAULT NULL,
  `verdict_reason` text DEFAULT NULL,
  `profile_picture` varchar(255) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `interview_status` enum('None','Proposed','Confirmed','Declined') DEFAULT 'None',
  `interview_datetime` datetime DEFAULT NULL,
  `interview_notes` text DEFAULT NULL,
  `interview_token` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `job_id` (`job_id`),
  KEY `fk_candidate_user` (`user_id`),
  CONSTRAINT `candidates_ibfk_1` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_candidate_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Data for `candidates` (57 rows)
-- ----------------------------
INSERT INTO `candidates` (`id`, `job_id`, `name`, `email`, `phone`, `filename`, `full_text`, `stripped_text`, `status`, `recommendation`, `overall_score`, `skills_match`, `exp_match`, `edu_match`, `summary`, `education`, `experience`, `skills`, `strengths`, `gaps`, `relevance_label`, `note`, `suggested_question`, `screened`, `created_at`, `user_id`, `resume_path`, `youtube_url`, `hiring_verdict`, `verdict_reason`, `profile_picture`, `updated_at`, `interview_status`, `interview_datetime`, `interview_notes`, `interview_token`) VALUES
('app_0a7d481d', '18', 'Test 5', NULL, NULL, '1_STRONG_HIRE_Elena_Voss.pdf', 'Elena Voss\nSenior Backend Engineer (Python)\nSingapore, SG  | +65 5588 2201  | elena.voss@fictionalmail.com  | linkedin.com/in/elenavoss-demo\nSUMMARY\nSenior backend engineer with 8 years building and scaling Python services for high-traffic platforms. Deep hands-on\nexpertise across the full stack requested for this role: FastAPI/Django, PostgreSQL, Redis, Kafka, containerized\ndeployments on AWS with Kubernetes, and mature CI/CD practice. Regularly leads architecture decisions and\nmentors junior engineers.\nSKILLS\nPython (8 yrs)  | FastAPI  | Django REST Framework  | PostgreSQL  | Redis  | Kafka  | RabbitMQ  | AWS (EKS,\nRDS, ElastiCache)  | Docker  | Kubernetes  | CI/CD (GitHub Actions, ArgoCD)  | System Architecture  | Mentoring &\nCode Review\nEXPERIENCE\nSenior Backend Engineer — Northfield Data Systems\nSingapore  | Jun 2020 – Present\n Designed and led migration of a monolithic Django app to FastAPI microservices on Kubernetes (EKS), cutting p95\nlatency by 46%.\n Built the event-streaming layer on Kafka handling 40M+ events/day, replacing a brittle polling system.\n Own the CI/CD pipeline (GitHub Actions ® ArgoCD) used by all 6 backend squads; deploys went from weekly to\nmultiple times daily.\n Mentor 3 junior engineers; run the team\'s architecture review sessions.\nBackend Engineer — Ridgeline Software\nSingapore  | Jul 2017 – May 2020\n Built REST APIs in Django REST Framework backed by PostgreSQL and Redis caching, serving 2M+ daily active\nusers.\n Containerized all services with Docker; introduced RabbitMQ for async job processing.\nSoftware Engineer — Cobalt Applications\nKuala Lumpur, MY  | Aug 2015 – Jun 2017\n Developed Python data-processing pipelines and internal tooling for a 20-person engineering team.\nEDUCATION\nB.Sc. in Computer Science — National University of Singapore, 2015\nCERTIFICATIONS\nAWS Certified Solutions Architect – Associate, Certified Kubernetes Application Developer (CKAD)', 'Elena Voss\nSenior Backend Engineer (Python)\nSingapore, SG  | +65 5588 2201  | [REDACTED EMAIL]  | linkedin.com/in/elenavoss-demo\nSUMMARY\nSenior backend engineer with 8 years building and scaling Python services for high-traffic platforms. Deep hands-on\nexpertise across the full stack requested for this role: FastAPI/Django, PostgreSQL, Redis, Kafka, containerized\ndeployments on AWS with Kubernetes, and mature CI/CD practice. Regularly leads architecture decisions and\nmentors junior engineers.\nSKILLS\nPython (8 yrs)  | FastAPI  | Django REST Framework  | PostgreSQL  | Redis  | Kafka  | RabbitMQ  | AWS (EKS,\nRDS, ElastiCache)  | Docker  | Kubernetes  | CI/CD (GitHub Actions, ArgoCD)  | System Architecture  | Mentoring &\nCode Review\nEXPERIENCE\nSenior Backend Engineer — Northfield Data Systems\nSingapore  | Jun 2020 – Present\n Designed and led migration of a monolithic Django app to FastAPI microservices on Kubernetes (EKS), cutting p95\nlatency by 46%.\n Built the event-streaming layer on Kafka handling 40M+ events/day, replacing a brittle polling system.\n Own the CI/CD pipeline (GitHub Actions ® ArgoCD) used by all 6 backend squads; deploys went from weekly to\nmultiple times daily.\n Mentor 3 junior engineers; run the team\'s architecture review sessions.\nBackend Engineer — Ridgeline Software\nSingapore  | Jul 2017 – May 2020\n Built REST APIs in Django REST Framework backed by PostgreSQL and Redis caching, serving 2M+ daily active\nusers.\n Containerized all services with Docker; introduced RabbitMQ for async job processing.\nSoftware Engineer — Cobalt Applications\nKuala Lumpur, MY  | Aug 2015 – Jun 2017\n Developed Python data-processing pipelines and internal tooling for a 20-person engineering team.\nEDUCATION\nB.Sc. in Computer Science — National University of Singapore, 2015\nCERTIFICATIONS\nAWS Certified Solutions Architect – Associate, Certified Kubernetes Application Developer (CKAD)', 'Review',