('6', '20', 'Marketing Executive', '{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"i did my internship at astro as marketing intern in marketing department\",\"role\":\"as marketing intern, im handling all social media for astro. posting updates, designing poster, and manage social media\",\"duration\":\"april 2024 - december 2024\",\"notes\":\"im handling all social media for astro. posting updates, designing poster, and manage social media\"},{\"company\":\"i have part time experience as cashier at 7 eleven\",\"role\":\"cashier\",\"duration\":\"april 2023 - july 2023\",\"notes\":\"set the minimum amount of money that should be in the cash drawer for opening, helping customer in transaction to ensure smooth operation, calculate total sales for the day before closing.\"}],\"education\":[{\"school\":\"multimedia university\",\"degree\":\"bachelor degree in mass communication\",\"year\":\"2025\"}],\"skills\":\"canva, excel, word, powerpoint, adobe illustrator, adobe premiere pro, adobe photoshop, mandarin, japanese\",\"extra_notes\":\"\",\"is_fresh_grad\":true,\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"\",\"location\":\"Kuala Lumpur\"}', '{\"summary\":\"Enthusiastic Mass Communication graduate from Multimedia University, eager to launch a career as a Marketing Executive. Combines a strong academic foundation in communication with practical internship experience in social media management, content creation, and digital design. Equipped with multilingual capabilities and proficiency in creative tools to contribute to dynamic marketing initiatives.\",\"experience\":[{\"company\":\"Astro\",\"role\":\"Marketing Intern\",\"duration\":\"April 2024 - December 2024\",\"bullets\":[\"Managed end-to-end social media operations for Astro, ensuring consistent brand messaging and active audience engagement.\",\"Designed visually appealing promotional posters and digital assets to support marketing campaigns.\",\"Curated, scheduled, and published regular content updates across various social media platforms to maximize online presence.\"]},{\"company\":\"7-Eleven\",\"role\":\"Cashier\",\"duration\":\"April 2023 - July 2023\",\"bullets\":[\"Facilitated smooth and efficient customer transactions to deliver a high-quality service experience.\",\"Managed cash drawer operations, including establishing opening balances and performing accurate end-of-day sales reconciliations.\",\"Demonstrated strong attention to detail and reliability in handling financial transactions and daily store closing procedures.\"]}],\"education\":[{\"degree\":\"Bachelor of Mass Communication\",\"school\":\"Multimedia University\",\"year\":\"2025\"}],\"skills\":[\"Canva\",\"Adobe Illustrator\",\"Adobe Premiere Pro\",\"Adobe Photoshop\",\"Microsoft Excel\",\"Microsoft Word\",\"Microsoft PowerPoint\",\"Mandarin\",\"Japanese\"],\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"\",\"location\":\"Kuala Lumpur\"}', '2026-09-07 15:14:18'),
('7', '20', 'Marketing Executive', '{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"i did my internship at astro as marketing intern in marketing department\",\"role\":\"as marketing intern, im handling all social media for astro. posting updates, designing poster, and manage social media\",\"duration\":\"april 2024 - december 2024\",\"notes\":\"im handling all social media for astro. posting updates, designing poster, and manage social media\"},{\"company\":\"i have part time experience as cashier at 7 eleven\",\"role\":\"cashier\",\"duration\":\"april 2023 - july 2023\",\"notes\":\"set the minimum amount of money that should be in the cash drawer for opening, helping customer in transaction to ensure smooth operation, calculate total sales for the day before closing.\"}],\"education\":[{\"school\":\"multimedia university\",\"degree\":\"bachelor degree in mass communication\",\"year\":\"2025\"}],\"skills\":\"canva, excel, word, powerpoint, adobe illustrator, adobe premiere pro, adobe photoshop, mandarin, japanese\",\"extra_notes\":\"\",\"is_fresh_grad\":true,\"full_name\":\"Test 5\",\"contact_email\":\"mommytobabydimples@lellol.dev\",\"contact_phone\":\"\",\"location\":\"Kuala Lumpur\"}', '{\"summary\":\"Motivated Mass Communication graduate from Multimedia University with practical experience in social media management and visual content creation from a marketing internship at Astro. Possesses strong foundational skills in digital design software, content execution, and multilingual communication. Eager to leverage creative and operational strengths to contribute as a Marketing Executive.\",\"experience\":[{\"company\":\"Astro\",\"role\":\"Marketing Intern\",\"duration\":\"April 2024 - December 2024\",\"bullets\":[\"Managed day-to-day social media operations for Astro, creating, scheduling, and publishing regular content updates.\",\"Designed promotional posters and graphic assets to support marketing initiatives across digital platforms.\