('23', '48', 'Marketing Executive', '{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"petronas\",\"role\":\"marketing\",\"duration\":\"2023 - present\",\"notes\":\"Managed social media channels to maintain consistent brand presence and active audience engagement.\\r\\nDeveloped and scheduled digital content using creative visual and video editing tools.\\r\\nAssisted in executing social media strategies aligned with overall marketing objectives.\\r\\nManaged social media channels to maintain a consistent brand presence and drive active audience engagement.\\r\\nProduced and scheduled digital content utilizing creative visual and video editing tools.\\r\\nSupported the execution of social media strategies aligned with overall marketing objectives.\"}],\"education\":[{\"school\":\"Taylor\'s University\",\"degree\":\"Degree in Mass Communication\",\"year\":\"2022\"}],\"skills\":\"Canva, Excel, Adobe Premiere Pro, Adobe Photoshop\",\"extra_notes\":\"google ads certificate\\r\\naws cloud practitioner\",\"is_fresh_grad\":false,\"full_name\":\"Desa\",\"contact_email\":\"newsgroupie@yellowt.site\",\"contact_phone\":\"6011-111111\",\"location\":\"Kuala Lumpur\",\"references\":[{\"name\":\"Sofea Cho\",\"title\":\"Former Manager at Petronas\",\"contact\":\"0173412444\"},{\"name\":\"Han Solo\",\"title\":\"Former HOD at Petronas\",\"contact\":\"0193412444\"}]}', '{\"summary\":\"Results-driven and creative Marketing Executive with practical experience in social media management, multimedia content creation, and digital strategy. Holds a Degree in Mass Communication from Taylor\'s University and demonstrates strong proficiency in creative design tools including Adobe Creative Cloud and Canva. Adept at building consistent brand messaging, designing captivating visual and video assets, and executing targeted social campaigns aligned with broader business objectives. Dedicated to driving audience engagement and enhancing overall brand presence through strategic digital storytelling.\",\"experience\":[{\"company\":\"Petronas\",\"role\":\"Marketing\",\"duration\":\"2023 - present\",\"bullets\":[\"Managed day-to-day operations across key social media channels, establishing a cohesive brand voice and fostering active community engagement.\",\"Conceptualized, edited, and scheduled multi-format visual and video content using visual design tools, ensuring alignment with brand standards.\",\"Supported the planning and execution of comprehensive social media campaigns structured around broader organizational marketing goals.\",\"Maintained structured content calendars to streamline publishing workflows and ensure consistent messaging across all digital touchpoints.\"]}],\"education\":[{\"degree\":\"Degree in Mass Communication\",\"school\":\"Taylor\'s University\",\"year\":\"2022\"}],\"skills\":[\"Canva\",\"Microsoft Excel\",\"Adobe Premiere Pro\",\"Adobe Photoshop\"],\"achievements\":[\"Google Ads Certification\",\"AWS Cloud Practitioner\"],\"full_name\":\"Desa\",\"contact_email\":\"newsgroupie@yellowt.site\",\"contact_phone\":\"6011-111111\",\"location\":\"Kuala Lumpur\",\"references\":[{\"name\":\"Sofea Cho\",\"title\":\"Former Manager at Petronas\",\"contact\":\"0173412444\"},{\"name\":\"Han Solo\",\"title\":\"Former HOD at Petronas\",\"contact\":\"0193412444\"}]}', '2026-09-28 11:54:45'),
('24', '48', 'Marketing Executive', '{\"target_title\":\"Marketing Executive\",\"experience\":[{\"company\":\"petronas\",\"role\":\"marketing\",\"duration\":\"2023 - present\",\"notes\":\"Managed social media channels to maintain consistent brand presence and active audience engagement.\\r\\nDeveloped and scheduled digital content using creative visual and video editing tools.\\r\\nAssisted in executing social media strategies aligned with overall marketing objectives.\\r\\nManaged social media channels to maintain a consistent brand presence and drive active audience engagement.\\r\\nProduced and scheduled digital content utilizing creative visual and video editing tools.\\r\\nSupported the execution of social media strategies aligned with overall marketing objectives.\"}],\"education\":[{\"school\":\"Taylor\'s University\",\"degree\":\"Degree in Mass Communication\",\"year\":\"2022\"}],\"skills\":\"Canva, Excel, Adobe Premiere Pro, Adobe Photoshop\",\"extra_notes\":\"google ads certificate\\r\\naws cloud practitioner\",\"is_fresh_grad\":false,\"full_name\":\"Desa\",\"contact_email\":\"newsgroupie@yellowt.site\",\"contact_phone\":\"6011-111111\",\"location\":\"Kuala Lumpur\",\"references\":[{\"name\":\"Sofea Cho\",\"title\":\"Former Manager at Petronas\",\"contact\":\"0173412444\"},{\"name\":\"Han Solo\",\"title\":\"Former HOD at Petronas\",\"contact\":\"0193412444\"}]}', '{\"summary\":\"Dynamic and detail-oriented Marketing Executive with a solid foundation in Mass Communication and corporate digital marketing operations. Proven expertise in managing multi-channel social media presences, crafting engaging visual and video content, and executing cohesive brand strategies. Skilled in leveraging industry-standard design tools including Adobe Creative Cloud and Canva to produce high-impact marketing assets. Brings a tech-savvy approach backed by Google Ads and cloud credentials to drive overall audience engagement and marketing alignment.\",\"experience\":[{\"company\":\"Petronas\",\"role\":\"Marketing Executive\",\"duration\":\"2023 - Present\",\"bullets\":[\"Manage dynamic social media channels to strengthen brand positioning, ensure messaging consistency, and drive continuous audience engagement.\",\"Design, edit, and schedule high-quality digital content and promotional multimedia using Canva, Adobe Photoshop, and Adobe Premiere Pro.\",\"Support the end-to-end execution of comprehensive social media campaigns aligned with corporate marketing goals and strategic priorities.\",\"Monitor channel activity and content distribution workflows to optimize online visibility and audience reach across digital touchpoints.\"]}],\"education\":[{\"degree\":\"Degree in Mass Communication\",\"school\":\"Taylor\'s University\",\"year\":\"2022\"}],\"skills\":[\"Canva\",\"Microsoft Excel\",\"Adobe Premiere Pro\",\"Adobe Photoshop\",\"Social Media Strategy\",\"Digital Content Creation\"],\"achievements\":[\"Google Ads Certification\",\"AWS Certified Cloud Practitioner\"],\"full_name\":\"Desa\",\"contact_email\":\"newsgroupie@yellowt.site\",\"contact_phone\":\"6011-111111\",\"location\":\"Kuala Lumpur\",\"references\":[{\"name\":\"Sofea Cho\",\"title\":\"Former Manager at Petronas\",\"contact\":\"0173412444\"},{\"name\":\"Han Solo\",\"title\":\"Former HOD at Petronas\",\"contact\":\"0193412444\"}]}', '2026-09-28 12:10:15'),
